#!/usr/bin/env python3
import sys
import os
import subprocess
import json
import datetime
import email.utils
import re
import html

FEEDS = {
    "CoinDesk": "https://www.coindesk.com/arc/outboundfeeds/rss/",
    "CoinTelegraph": "https://cointelegraph.com/rss",
    "Decrypt": "https://decrypt.co/feed",
    "Google News": "https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en",
    "BeInCrypto": "https://beincrypto.com/feed/",
    "The Block": "https://www.theblock.co/rss.xml",
    "CryptoSlate": "https://cryptoslate.com/feed/",
    "CryptoFox Markets": "https://cryptofox.news/rss/markets/",
    "CryptoFox Regulation": "https://cryptofox.news/rss/regulation/"
}

SOURCE_PRIORITY = {
    "CoinDesk": 1,
    "CoinTelegraph": 2,
    "Decrypt": 3,
    "The Block": 4,
    "BeInCrypto": 5,
    "CryptoSlate": 6,
    "CryptoFox Markets": 7,
    "CryptoFox Regulation": 7,
    "CryptoFox": 7,
    "Google News": 8
}

STOP_WORDS = {"the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "with", "by", "of", "from", "as", "is", "are", "was", "were", "be", "been", "has", "have", "had", "that", "this", "it", "its", "at", "about", "says", "report", "according", "new", "crypto", "cryptocurrency", "bitcoin", "ethereum", "solana", "xrp"}
MAJOR_SOURCES = {"CoinDesk", "CoinTelegraph", "Decrypt", "BeInCrypto", "The Block"}

def clean_string(s):
    if not s:
        return ""
    s = re.sub(r'<!\[CDATA\[([\s\S]*?)\]\]>', r'\1', s)
    s = re.sub(r'<[^>]*>', '', s)
    s = html.unescape(s)
    s = " ".join(s.split())
    return s.strip()

def parse_date(date_str):
    if not date_str:
        return None
    date_str = date_str.strip()
    try:
        dt = email.utils.parsedate_to_datetime(date_str)
        return dt.astimezone(datetime.timezone.utc)
    except Exception:
        pass
    try:
        if date_str.endswith('Z'):
            date_str = date_str[:-1] + '+00:00'
        dt = datetime.datetime.fromisoformat(date_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)
    except Exception:
        pass
    return None

def is_meme_coin_pump(headline, summary):
    text = (headline + " " + summary).lower()
    meme_words = ["dogecoin", "doge", "shiba", "pepe", "bonk", "wif", "floki", "memecoin", "meme coin"]
    for word in meme_words:
        if re.search(r'\b' + re.escape(word) + r'\b', text):
            pump_words = ["pump", "surge", "soar", "rally", "skyrocket", "gain", "rise", "bull", "price", "up", "ath", "high"]
            if any(pw in text for pw in pump_words):
                return True
    return False

def parse_with_regex(name, data_str):
    items = []
    matches = re.findall(r'<item(?:\s[^>]*)?>([\s\S]*?)<\/item>|<entry(?:\s[^>]*)?>([\s\S]*?)<\/entry>', data_str, re.IGNORECASE)
    for match in matches:
        content = match[0] if match[0] else match[1]

        title_m = re.search(r'<title(?:\s[^>]*)?>([\s\S]*?)<\/title>', content, re.IGNORECASE)
        title = title_m.group(1).strip() if title_m else ""

        link_m = re.search(r'<link(?:\s[^>]*)?>([\s\S]*?)<\/link>', content, re.IGNORECASE)
        link = ""
        if link_m:
            link = link_m.group(1).strip()
        else:
            href_m = re.search(r'<link(?:\s[^>]*)?\shref=["\']([^"\']+)["\']', content, re.IGNORECASE)
            if href_m:
                link = href_m.group(1).strip()

        pub_m = re.search(r'<(pubDate|published|updated)(?:\s[^>]*)?>([\s\S]*?)<\/\1>', content, re.IGNORECASE)
        pub_date = pub_m.group(2).strip() if pub_m else ""

        desc_m = re.search(r'<(description|summary)(?:\s[^>]*)?>([\s\S]*?)<\/\1>', content, re.IGNORECASE)
        desc = desc_m.group(2).strip() if desc_m else ""

        items.append({
            "source": name,
            "title": title,
            "link": link,
            "description": desc,
            "pubDate": pub_date
        })
    return items

def parse_feed_data(name, data_bytes):
    raw_items = []
    data_str = data_bytes.decode('utf-8', errors='ignore')

    try:
        raw_items = parse_with_regex(name, data_str)
    except Exception as e:
        print(f"Regex parse failed for {name}: {e}", file=sys.stderr)

    # Clean the extracted strings
    cleaned_items = []
    for item in raw_items:
        title = clean_string(item["title"])
        link = clean_string(item["link"])
        desc = clean_string(item["description"])
        pub_date = clean_string(item["pubDate"])

        if len(desc) > 280:
            desc = desc[:277] + "..."

        if title and link:
            cleaned_items.append({
                "source": name,
                "title": title,
                "link": link,
                "description": desc,
                "pubDate": pub_date
            })

    return cleaned_items

def fetch_feed_with_curl(name, url):
    ua = "Mozilla/5.0 (compatible; OpenClawScout/1.0)"
    cmd = ["curl", "-sL", "-A", ua, "--max-time", "12", url]
    try:
        res = subprocess.run(cmd, capture_output=True, text=False)
        if res.returncode == 0 and res.stdout:
            return res.stdout
        else:
            print(f"Curl failed for {name} with return code {res.returncode}", file=sys.stderr)
            return None
    except Exception as e:
        print(f"Exception during curl for {name}: {e}", file=sys.stderr)
        return None

def get_significant_tokens(title):
    cleaned = re.sub(r'[^a-zA-Z0-9\s]', '', title.lower())
    tokens = set(cleaned.split())
    return tokens - STOP_WORDS

def are_near_identical(title1, title2):
    tokens1 = get_significant_tokens(title1)
    tokens2 = get_significant_tokens(title2)
    if not tokens1 or not tokens2:
        return False
    intersection = tokens1.intersection(tokens2)
    smaller_len = min(len(tokens1), len(tokens2))
    overlap = len(intersection) / smaller_len
    return overlap >= 0.8

def check_history(url):
    script_path = os.path.expanduser("~/.openclaw/workspace-researcher/skills/history/article_history.sh")
    cmd = ["bash", script_path, "check", url]
    try:
        res = subprocess.run(cmd, capture_output=True, text=True, check=True)
        out = res.stdout.strip()
        return out
    except Exception as e:
        print(f"Error checking history for {url}: {e}", file=sys.stderr)
        return "NOT_FOUND"

def is_seriously_cross_covered(cand):
    sources = {cand["source"]}
    for corrob in cand["corroborating_sources"]:
        sources.add(corrob["source"])
    major_count = len(sources.intersection(MAJOR_SOURCES))
    return major_count >= 2

def main():
    if len(sys.argv) < 3:
        print("Usage: run_headline_scan.py <output_file> <target_count>", file=sys.stderr)
        sys.exit(1)

    output_file = sys.argv[1]
    target_count = int(sys.argv[2])

    print(f"Starting headline scan. Output target: {output_file}, Count: {target_count}", file=sys.stderr)

    # Step 1 & 2: Fetch and Parse feeds
    feed_items_map = {}
    for name, url in FEEDS.items():
        data_bytes = fetch_feed_with_curl(name, url)
        if data_bytes:
            items = parse_feed_data(name, data_bytes)
            feed_items_map[name] = items
            print(f"Fetched and parsed {len(items)} items from {name}", file=sys.stderr)
        else:
            print(f"Failed to fetch {name}", file=sys.stderr)

    # Step 3: Date Filtering & Meme filter tagging
    now_utc = datetime.datetime.now(datetime.timezone.utc)
    twenty_four_hours_ago = now_utc - datetime.timedelta(hours=24)

    raw_list = []
    for name, items in feed_items_map.items():
        for index, item in enumerate(items):
            url = item["link"]
            if not url or url.startswith("mailto:") or url.startswith("javascript:"):
                continue

            parsed_dt = parse_date(item["pubDate"])
            is_recent = False
            iso_date_str = ""

            if parsed_dt:
                is_recent = (parsed_dt >= twenty_four_hours_ago)
                iso_date_str = parsed_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
            else:
                if index < 5:
                    is_recent = True
                    iso_date_str = item["pubDate"]

            if not is_recent:
                continue

            is_meme = is_meme_coin_pump(item["title"], item["description"])

            raw_list.append({
                "source": item["source"],
                "title": item["title"],
                "link": item["link"],
                "description": item["description"],
                "pub_date": iso_date_str,
                "parsed_dt": parsed_dt,
                "is_meme": is_meme
            })

    # Step 4: Same-story and URL Deduplication
    candidates = []
    for item in raw_list:
        # URL Deduplication
        url_exists = False
        for cand in candidates:
            if cand["url"] == item["link"]:
                url_exists = True
                break
        if url_exists:
            continue

        # Same-story Deduplication
        found_dup_idx = -1
        for idx, cand in enumerate(candidates):
            if are_near_identical(cand["headline"], item["title"]):
                found_dup_idx = idx
                break

        if found_dup_idx != -1:
            existing = candidates[found_dup_idx]
            p_existing = SOURCE_PRIORITY.get(existing["source"], 9)
            p_new = SOURCE_PRIORITY.get(item["source"], 9)

            if p_new < p_existing:
                # Replace existing
                corrob = {"source": existing["source"], "url": existing["url"]}
                new_corroborating = existing["corroborating_sources"] + [corrob]
                new_corroborating = new_corroborating[:2]

                replacement = {
                    "headline": item["title"],
                    "url": item["link"],
                    "pub_date": item["pub_date"],
                    "parsed_dt": item["parsed_dt"],
                    "source": item["source"],
                    "summary": item["description"],
                    "corroborating_sources": new_corroborating,
                    "is_meme": item["is_meme"] or existing["is_meme"]
                }
                candidates[found_dup_idx] = replacement
            else:
                corrob = {"source": item["source"], "url": item["link"]}
                if corrob not in existing["corroborating_sources"]:
                    existing["corroborating_sources"].append(corrob)
                    existing["corroborating_sources"] = existing["corroborating_sources"][:2]
                if item["is_meme"]:
                    existing["is_meme"] = True
        else:
            candidates.append({
                "headline": item["title"],
                "url": item["link"],
                "pub_date": item["pub_date"],
                "parsed_dt": item["parsed_dt"],
                "source": item["source"],
                "summary": item["description"],
                "corroborating_sources": [],
                "is_meme": item["is_meme"]
            })

    # Apply meme-coin filter to the deduplicated candidates
    surviving_candidates = []
    for cand in candidates:
        if cand["is_meme"]:
            if is_seriously_cross_covered(cand):
                surviving_candidates.append(cand)
            else:
                print(f"Dropping meme pump headline (no cross-coverage): {cand['headline']}", file=sys.stderr)
        else:
            surviving_candidates.append(cand)

    # Step 5: Persistent dedup gate (URL history)
    history_checked_candidates = []
    for cand in surviving_candidates:
        status = check_history(cand["url"])
        if status == "NOT_FOUND":
            history_checked_candidates.append(cand)
        else:
            print(f"Dropping candidate because it exists in history: {cand['headline']}", file=sys.stderr)

    # Sort candidates
    with_dt = []
    without_dt = []
    for cand in history_checked_candidates:
        if cand.get("parsed_dt"):
            with_dt.append(cand)
        else:
            without_dt.append(cand)

    with_dt.sort(key=lambda x: x["parsed_dt"], reverse=True)
    sorted_candidates = with_dt + without_dt

    # Trim to target count
    final_candidates = sorted_candidates[:target_count]

    # Remove temp and cleanup fields
    for i, cand in enumerate(final_candidates):
        cand["candidate_index"] = i + 1
        if "parsed_dt" in cand:
            del cand["parsed_dt"]
        if "is_meme" in cand:
            del cand["is_meme"]

    output_data = {
        "status": "ok",
        "mode": "headline_scan",
        "scanned_at": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "target_count": target_count,
        "candidate_count": len(final_candidates),
        "candidates": final_candidates
    }

    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    with open(output_file, "w") as f:
        json.dump(output_data, f, indent=2)

    print(f"Successfully wrote {len(final_candidates)} candidates to {output_file}", file=sys.stderr)

if __name__ == "__main__":
    main()
